ALTER TABLE public.app_roles ADD COLUMN biz_detail_exception boolean NOT NULL DEFAULT false;
UPDATE public.app_roles SET biz_detail_exception=true WHERE id IN ('role-admin','role-viewer');
COMMENT ON COLUMN public.app_roles.biz_scope IS 'DEPRECATED: business default scope now comes from effective appointments; explicit exceptions use biz_access_exceptions or biz_detail_exception.';
ALTER TABLE public.biz_positions ADD COLUMN business_policy text NOT NULL DEFAULT 'personal' CHECK(business_policy IN ('personal','manager','executive'));
ALTER TABLE public.biz_positions ADD COLUMN all_business boolean NOT NULL DEFAULT false;
UPDATE public.biz_positions SET business_policy=CASE WHEN unit_kind='individual' THEN 'personal' ELSE 'manager' END;
CREATE TABLE public.biz_access_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),role_id text REFERENCES public.app_roles(id),permission text NOT NULL CHECK(permission LIKE 'biz.%'),scope_kind text NOT NULL CHECK(scope_kind IN ('individual','team','department','system','all')),system_id uuid REFERENCES public.biz_systems(id),department_id uuid REFERENCES public.biz_departments(id),team_id uuid REFERENCES public.biz_teams(id),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,revoked_at timestamptz,granted_by uuid NOT NULL REFERENCES public.profiles(id),reason text NOT NULL CHECK(btrim(reason)<>''),created_at timestamptz NOT NULL DEFAULT now(),CHECK((user_id IS NULL)<>(role_id IS NULL)),CHECK(ended_at IS NULL OR ended_at>started_at));
GRANT SELECT ON public.biz_access_exceptions TO authenticated;
GRANT ALL ON public.biz_access_exceptions TO service_role;
ALTER TABLE public.biz_access_exceptions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.biz_exception_ok(_actor uuid,_permission text,_kind text DEFAULT NULL,_unit uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.biz_access_exceptions e WHERE (e.user_id=_actor OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_actor AND r.role_id=e.role_id)) AND e.permission=_permission AND e.revoked_at IS NULL AND e.started_at<=now() AND (e.ended_at IS NULL OR e.ended_at>now()) AND (_kind IS NULL OR e.scope_kind='all' OR (e.scope_kind=_kind AND CASE _kind WHEN 'system' THEN e.system_id WHEN 'department' THEN e.department_id WHEN 'team' THEN e.team_id ELSE e.user_id END IS NOT DISTINCT FROM _unit)))$$;
CREATE FUNCTION public.biz_participant(_actor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_actor AND p.status='Đang hoạt động') AND (EXISTS(SELECT 1 FROM public.biz_department_members m WHERE m.user_id=_actor) OR EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND a.status<>'cancelled' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now())) OR EXISTS(SELECT 1 FROM public.biz_management_assignments a WHERE a.user_id=_actor AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now())) OR EXISTS(SELECT 1 FROM public.user_roles u JOIN public.app_roles r ON r.id=u.role_id WHERE u.user_id=_actor AND EXISTS(SELECT 1 FROM unnest(r.permissions) v WHERE v LIKE 'biz.%')))$$;
CREATE FUNCTION public.biz_manager(_actor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND a.status<>'cancelled' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()) AND coalesce(a.position_snapshot->>'business_policy',CASE WHEN a.scope_kind='individual' THEN 'personal' ELSE 'manager' END) IN ('manager','executive')) OR EXISTS(SELECT 1 FROM public.biz_management_assignments a WHERE a.user_id=_actor AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()))$$;
CREATE OR REPLACE FUNCTION public.biz_all_scope(_actor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_actor AND status='Đang hoạt động') AND (public.is_super_admin(_actor) OR EXISTS(SELECT 1 FROM public.user_roles u JOIN public.app_roles r ON r.id=u.role_id WHERE u.user_id=_actor AND r.biz_detail_exception) OR public.biz_exception_ok(_actor,'biz.view_all','all') OR EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND a.status<>'cancelled' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()) AND coalesce((a.position_snapshot->>'all_business')::boolean,false) AND a.position_snapshot->>'business_policy'='executive'))$$;
CREATE FUNCTION public.biz_can(_actor uuid,_permission text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$BEGIN
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_actor AND status='Đang hoạt động') THEN RETURN false;END IF;
IF public.is_super_admin(_actor) THEN RETURN true;END IF;
IF _permission NOT LIKE 'biz.%' THEN RETURN private.sig_can(_actor,_permission);END IF;
IF public.biz_exception_ok(_actor,_permission) THEN RETURN true;END IF;
IF _permission='biz.view_all' THEN RETURN public.biz_all_scope(_actor);END IF;
IF _permission='biz.dashboard_public' THEN RETURN public.biz_participant(_actor) OR public.biz_all_scope(_actor);END IF;
IF _permission IN ('biz.view_dept','biz.approval_view') THEN RETURN public.biz_manager(_actor) OR public.biz_all_scope(_actor) OR EXISTS(SELECT 1 FROM public.biz_approval_runs r WHERE r.status='pending' AND (r.steps->r.current_step->>'user_id'=_actor::text OR r.steps->r.current_step->>'substitute_id'=_actor::text));END IF;
IF _permission IN ('biz.view_own','biz.plan_submit','biz.goal_submit','biz.report_submit') THEN RETURN public.biz_participant(_actor) AND (NOT EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND a.status<>'cancelled' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()) AND a.position_snapshot->>'business_policy'='executive') OR EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND a.status<>'cancelled' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()) AND coalesce(a.position_snapshot->>'business_policy','personal')<>'executive'));END IF;
IF _permission='biz.plan_request_revision' THEN RETURN public.biz_manager(_actor);END IF;
IF _permission IN ('biz.goal_approve','biz.report_approve','biz.late_approve') THEN RETURN public.biz_manager(_actor) OR EXISTS(SELECT 1 FROM public.biz_approval_runs r WHERE r.status='pending' AND (r.steps->r.current_step->>'user_id'=_actor::text OR r.steps->r.current_step->>'substitute_id'=_actor::text));END IF;
IF _permission='biz.plan_approve' THEN RETURN false;END IF;
RETURN private.sig_can(_actor,_permission) AND NOT EXISTS(SELECT 1 FROM public.user_roles u WHERE u.user_id=_actor AND u.role_id='role-xwbmhg3b' AND NOT EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.app_roles r ON r.id=ur.role_id WHERE ur.user_id=_actor AND ur.role_id<>u.role_id AND _permission=ANY(r.permissions)));
END $$;
CREATE OR REPLACE FUNCTION public.biz_role_scope_allows(_actor uuid,_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT public.is_super_admin(_actor) OR public.biz_manager(_actor) OR public.biz_all_scope(_actor) OR (_kind='individual' AND public.biz_participant(_actor))$$;
CREATE OR REPLACE FUNCTION public.biz_scope_ok(_actor uuid,_user uuid,_dept uuid,_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_actor AND status='Đang hoạt động') AND (public.biz_all_scope(_actor) OR EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND coalesce(a.position_snapshot->>'business_policy',CASE WHEN a.scope_kind='individual' THEN 'personal' ELSE 'manager' END) IN ('manager','executive') AND public.biz_appointment_scope(a.id,_user,_dept,_at)) OR EXISTS(SELECT 1 FROM public.biz_management_assignments a WHERE a.user_id=_actor AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()) AND ((a.position='director' AND EXISTS(SELECT 1 FROM public.biz_department_system_history h WHERE h.department_id=_dept AND h.system_id=a.system_id AND h.started_at<=_at AND (h.ended_at IS NULL OR h.ended_at>_at))) OR (a.position='department_head' AND a.department_id=_dept) OR (a.position='team_lead' AND EXISTS(SELECT 1 FROM public.biz_team_members m JOIN public.biz_teams t ON t.id=m.team_id WHERE m.user_id=_user AND m.team_id=a.team_id AND t.department_id=_dept AND m.started_at<=_at AND (m.ended_at IS NULL OR m.ended_at>_at))))) OR public.biz_exception_ok(_actor,'biz.view_dept','department',_dept) OR EXISTS(SELECT 1 FROM public.biz_department_system_history h WHERE h.department_id=_dept AND h.started_at<=_at AND (h.ended_at IS NULL OR h.ended_at>_at) AND public.biz_exception_ok(_actor,'biz.view_dept','system',h.system_id)) OR EXISTS(SELECT 1 FROM public.biz_team_members m JOIN public.biz_teams t ON t.id=m.team_id WHERE m.user_id=_user AND t.department_id=_dept AND m.started_at<=_at AND (m.ended_at IS NULL OR m.ended_at>_at) AND public.biz_exception_ok(_actor,'biz.view_dept','team',m.team_id)))$$;
-- Route every existing business-only permission gate through the authoritative business resolver. Non-business modules and private.sig_can are unchanged.
DO $$DECLARE f record;def text;BEGIN FOR f IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'biz_%' AND proname NOT IN ('biz_can','biz_all_scope','biz_exception_ok','biz_participant','biz_manager','biz_scope_ok','biz_role_scope_allows') LOOP SELECT pg_get_functiondef(f.oid) INTO def;IF position('private.sig_can(' IN def)>0 THEN EXECUTE replace(def,'private.sig_can(','public.biz_can(');END IF;END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.biz_goal_can_review(_user_id uuid,_department_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT _user_id<>auth.uid() AND (public.is_super_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.biz_goal_versions v JOIN public.biz_annual_goals g ON g.id=v.goal_id JOIN public.biz_approval_runs r ON r.version_id=v.id WHERE g.user_id=_user_id AND g.department_id=_department_id AND r.status='pending' AND public.biz_run_assigned(v.id,true) AND public.biz_step_scope_ok(r.steps,r.current_step,auth.uid(),r.owner_id,r.department_id,r.submitted_at)))$$;
CREATE OR REPLACE FUNCTION public.biz_doc_access(_user uuid,_dept uuid,_kind text,_review boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='Đang hoạt động') AND CASE WHEN _kind NOT IN ('plan','report') THEN false WHEN _review THEN _user<>auth.uid() AND (public.is_super_admin(auth.uid()) OR (_kind='plan' AND public.biz_can(auth.uid(),'biz.plan_request_revision') AND public.biz_scope_ok(auth.uid(),_user,_dept)) OR (_kind='report' AND EXISTS(SELECT 1 FROM public.biz_document_versions v JOIN public.biz_documents d ON d.id=v.document_id JOIN public.biz_approval_runs r ON r.version_id=v.id WHERE d.user_id=_user AND d.department_id=_dept AND d.kind='report' AND r.status='pending' AND public.biz_run_assigned(v.id,true) AND public.biz_step_scope_ok(r.steps,r.current_step,auth.uid(),r.owner_id,r.department_id,r.submitted_at)))) ELSE public.biz_all_scope(auth.uid()) OR (_user=auth.uid() AND public.biz_participant(auth.uid())) OR public.biz_scope_ok(auth.uid(),_user,_dept) OR (_kind='report' AND EXISTS(SELECT 1 FROM public.biz_document_versions v JOIN public.biz_documents d ON d.id=v.document_id WHERE d.user_id=_user AND d.department_id=_dept AND d.kind='report' AND public.biz_run_assigned(v.id))) END$$;
CREATE OR REPLACE FUNCTION public.biz_goal_can_read(_goal_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.biz_annual_goals g WHERE g.id=_goal_id AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='Đang hoạt động') AND (public.biz_all_scope(auth.uid()) OR (g.user_id=auth.uid() AND public.biz_participant(auth.uid())) OR public.biz_scope_ok(auth.uid(),g.user_id,g.department_id) OR EXISTS(SELECT 1 FROM public.biz_goal_versions v WHERE v.goal_id=g.id AND public.biz_run_assigned(v.id))))$$;
CREATE OR REPLACE FUNCTION public.biz_run_can_read(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.biz_approval_runs r WHERE r.id=_id AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='Đang hoạt động') AND (public.biz_all_scope(auth.uid()) OR r.owner_id=auth.uid() OR public.biz_scope_ok(auth.uid(),r.owner_id,r.department_id,r.submitted_at) OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.steps) s WHERE s->>'user_id'=auth.uid()::text OR s->>'substitute_id'=auth.uid()::text)))$$;
CREATE FUNCTION public.biz_effective_access(_user uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=coalesce(_user,auth.uid());perms jsonb;BEGIN IF auth.uid() IS NULL OR (u<>auth.uid() AND NOT public.biz_org_can_manage() AND NOT private.sig_can(auth.uid(),'settings.role')) THEN RAISE EXCEPTION 'Không có quyền xem quyền nhân sự.';END IF;SELECT coalesce(jsonb_agg(p),'[]') INTO perms FROM unnest(ARRAY['biz.dashboard_public','biz.view_own','biz.view_dept','biz.view_all','biz.plan_submit','biz.goal_submit','biz.report_submit','biz.plan_request_revision','biz.goal_approve','biz.report_approve','biz.late_approve','biz.approval_view','biz.org_manage','biz.dept_manage','biz.kr_manage','biz.deadline_manage','biz.workflow_manage']) p WHERE public.biz_can(u,p);RETURN jsonb_build_object('user_id',u,'permissions',perms,'server_now',now(),'super_admin',public.is_super_admin(u),'appointments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'position',a.position_snapshot->>'name','scope',a.scope_kind,'unit_name',CASE a.scope_kind WHEN 'system' THEN (SELECT name FROM public.biz_systems WHERE id=a.system_id) WHEN 'department' THEN (SELECT name FROM public.biz_departments WHERE id=a.department_id) WHEN 'team' THEN (SELECT name FROM public.biz_teams WHERE id=a.team_id) ELSE 'Cá nhân' END,'started_at',a.started_at,'ended_at',a.ended_at)),'[]') FROM public.biz_appointments a WHERE a.user_id=u AND a.status<>'cancelled' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now())),'legacy_assignments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'position',coalesce(p.name,a.position),'scope',p.unit_kind,'unit_name',coalesce(s.name,d.name,t.name),'started_at',a.started_at,'ended_at',a.ended_at)),'[]') FROM public.biz_management_assignments a LEFT JOIN public.biz_positions p ON p.code=a.position LEFT JOIN public.biz_systems s ON s.id=a.system_id LEFT JOIN public.biz_departments d ON d.id=a.department_id LEFT JOIN public.biz_teams t ON t.id=a.team_id WHERE a.user_id=u AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now())),'exceptions',(SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]') FROM public.biz_access_exceptions e WHERE (e.user_id=u OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role_id=e.role_id)) AND e.revoked_at IS NULL AND e.started_at<=now() AND (e.ended_at IS NULL OR e.ended_at>now())),'role_exceptions',(SELECT coalesce(jsonb_agg(jsonb_build_object('role_id',r.id,'role_name',r.name,'permission','biz.view_all','scope','all','reason','Giữ quyền xem chi tiết toàn Khối theo quyết định chuyển đổi đã xác nhận')),'[]') FROM public.user_roles ur JOIN public.app_roles r ON r.id=ur.role_id WHERE ur.user_id=u AND r.biz_detail_exception),'next_change',(SELECT min(at_) FROM (SELECT a.started_at at_ FROM public.biz_appointments a WHERE a.user_id=u AND a.status<>'cancelled' UNION ALL SELECT a.ended_at FROM public.biz_appointments a WHERE a.user_id=u AND a.status<>'cancelled' UNION ALL SELECT a.started_at FROM public.biz_management_assignments a WHERE a.user_id=u UNION ALL SELECT a.ended_at FROM public.biz_management_assignments a WHERE a.user_id=u UNION ALL SELECT e.started_at FROM public.biz_access_exceptions e WHERE e.user_id=u OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role_id=e.role_id) UNION ALL SELECT e.ended_at FROM public.biz_access_exceptions e WHERE e.user_id=u OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role_id=e.role_id)) q WHERE at_>now()));END$$;
CREATE POLICY biz_exception_read ON public.biz_access_exceptions FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles u WHERE u.user_id=auth.uid() AND u.role_id=biz_access_exceptions.role_id) OR public.is_super_admin(auth.uid()) OR private.sig_can(auth.uid(),'settings.role'));
REVOKE ALL ON FUNCTION public.biz_exception_ok(uuid,text,text,uuid),public.biz_participant(uuid),public.biz_manager(uuid),public.biz_can(uuid,text),public.biz_effective_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_can(uuid,text),public.biz_effective_access(uuid),public.biz_participant(uuid),public.biz_manager(uuid),public.biz_exception_ok(uuid,text,text,uuid) TO authenticated;
